"""Archive every solver trace generated by the existing verification routine."""
from unittest.mock import patch
from nr2d import checks
from nr2d.physics import SpatialModel
from nr2d.experiments import ROOT, RUNS, read_json, write_json

run = ROOT/read_json(RUNS/"latest.json")["run"].replace("\\", "/")
records = []


class RecordingModel(SpatialModel):
    def simulate(self, *args, **kwargs):
        result = super().simulate(*args, **kwargs)
        name = f"verification/solve_{len(records):02d}.npz"
        result.save(run/name)
        records.append({"path": name, "config": result.config, "wall_seconds": result.wall_seconds})
        return result


# Instrument output capture only; the solver and check implementation are unchanged.
with patch.object(checks, "SpatialModel", RecordingModel):
    report, _ = checks.run_checks()
write_json(run/"verification/index.json", {"traces": records, "report": report,
           "capture": "Recording subclass; same unmodified physical solver and verification routine"})
assert report["passed"]
print(f"Archived {len(records)} verification traces; {report['wall_seconds']:.2f} s")
